def check_partition(m):
    S = set(range(3, m + 1))
    for i in range(2**(m - 2)):
        subset1 = {list(S)[j] for j in range(m - 2) if (i & (1 << j)) > 0}
        subset2 = S - subset1
        found = False
        for a in subset1:
            for b in subset1:
                c = a * b
                if c in subset1 or subset2:
                    found = True
                    break
            if found:
                break
        if not found:
            return False
    return True

m = 3
while True:
    if check_partition(m):
        break
    m += 1

print(m)
